t='.....((((.(((((....))....))).(((....))).)).)).....((((.((((....))...)).(((....))).))..))....................'
print('len',len(t))
# parse pairs
stack=[]
pairs={}
for i,c in enumerate(t):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop()
        pairs[j]=i
        pairs[i]=j
for i in sorted(pairs):
    if i<pairs[i]:
        print(i,'-',pairs[i])
